UPDATE companies SET description='Amy Food Inc. operates from Houston, Texas, where it has spent three decades as a family-owned business. The company was founded on a passion for authentic Asian cuisine, though the exact founding year and founder names are not publicly disclosed.

The company manufactures a line of frozen Asian-style appetizers that includes potsticker dumplings, egg rolls, crab rangoon, cream cheese wontons, empanadas and broth. Several items are sold under the Jamy''s Three Dragon label. A notable capability is the in-house production of egg roll wrappers. Products are offered in pork, chicken and vegetable varieties, shipped frozen, and designed to be prepared by baking, deep frying, air frying or pan searing.

Amy Food serves both foodservice and retail channels.

The company states that its differentiation comes from blending time-honored recipes with meticulous care to deliver meals that taste like home, a philosophy that has guided its 30-year journey.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Frozen appetizer manufacturing", "In-house egg roll wrapper production", "Dumpling production", "Egg roll production", "Empanada production", "Crab rangoon production", "Cream cheese wonton production", "Broth production"], "industries": ["Foodservice", "Retail"], "materials": ["Pork", "Chicken", "Vegetables"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned with 30 years of experience", "In-house egg roll wrapper production", "Frozen products suitable for multiple cooking methods (bake, deep fry, air fry, pan sear)", "Authentic Asian recipes blended with meticulous care"], "facts_used": ["Family-owned food producer in Houston, Texas -> db", "30-year journey as family-owned business -> page:/", "Product line: potsticker dumplings, egg rolls, crab rangoon, cream cheese wontons, empanadas, broth -> db", "Jamy''s Three Dragon label -> db", "In-house egg roll wrapper production -> db", "Pork, chicken, vegetable varieties -> db", "Shipped frozen, multiple cooking methods -> db", "Serves foodservice and retail customers -> db", "Blends time-honored recipes with meticulous care -> page:/"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Amy Food Inc. is a family-owned food producer based in Houston, Texas, focused on frozen Asian-style appetizers.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='amy-food-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Anchor Ingredients is headquartered in Fargo, North Dakota. The privately owned company operates offices, manufacturing facilities, and warehouses across the United States.

The company functions as a specialty ingredient supplier and contract manufacturer, offering farm-level sourcing partnerships, custom processing, freeze-dry co-manufacturing, blending, distribution, and logistics management. Its facilities employ advanced technologies for processing and quality assurance, supported by a supplier approval program and in-house testing validated by third parties.

Anchor Ingredients serves the pet food and human food industries, providing conventional and organic ingredients to brands seeking traceable supply chains. Customers include food manufacturers looking for end-to-end connectivity from farm to finished product.

Founded on a mission to cultivate connectivity and quality across the food supply chain, the company emphasizes transparency, traceability, and a customer-centric approach. Its AnchorCONNECT portal gives clients real-time access to certificates of analysis, bills of lading, and traceability reports for every order.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom processing", "Freeze-dry co-manufacturing", "Logistics and supply chain management", "Farm-level sourcing partnerships", "Blending", "Distribution", "Quality assurance and testing", "Supplier approval program", "Innovation and technology services"], "industries": ["Pet food", "Human food"], "materials": ["Conventional food ingredients", "Organic food ingredients"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Farm-level partnerships ensuring ingredient traceability", "Freeze-dry co-manufacturing capabilities", "AnchorCONNECT customer portal for real-time document access", "Team trained in PCQI, HACCP, and SQF implementation", "Nationwide network of manufacturing facilities and warehouses"], "facts_used": ["Headquartered in Fargo, North Dakota -> /about", "Privately owned company -> /about", "Offices, manufacturing facilities, and warehouse locations across the country -> /about", "Specialty ingredient supplier and contract manufacturer offering farm-level sourcing, custom processing, freeze-dry co-manufacturing, blending, distribution, logistics -> /services", "Facilities employ advanced technologies for processing and quality assurance -> /quality", "Supplier approval program and in-house testing validated by third parties -> /quality", "Serves pet food and human food industries -> /", "Provides conventional and organic ingredients -> /", "Mission to cultivate connectivity and quality across food supply chain -> /about", "Emphasizes transparency, traceability, customer-centric approach -> /about, /quality", "AnchorCONNECT portal for real-time access to